backend.types:
export interface AuthUser {
    /** Stable AppDeploy user ID (UUID) */
    userId: string;
    /** User's email address (requires 'email' scope) */
    email?: string;
    /** User's display name (requires 'profile' scope) */
    name?: string;
    /** Space-separated list of granted scopes */
    scope: string;
}

// --- Router helpers ---

/** Context passed to each route middleware */
export interface RouterContext {
    /** Parsed request body */
    body: unknown;
    /** Query string parameters */
    query: Record<string, string>;
    /** URL path parameters (e.g., :id) */
    params: Record<string, string>;
    /** Raw Lambda event */
    event: any;
    /** Authenticated user (set by requireAuth middleware) */
    user?: AuthUser;
}

/** Standard JSON response returned by route handlers */
export interface RouterResponse {
    statusCode: number;
    headers: Record<string, string>;
    body: string;
}

/** A route middleware function */
export type RouterMiddleware = (
    ctx: RouterContext
) => Promise<RouterResponse | void> | RouterResponse | void;

/** Route definitions: pattern string → middleware chain */
export type RouterRoutes = Record<string, RouterMiddleware[]>;

/**
 * Create a Lambda handler that routes requests through middleware chains.
 *
 * @example
 * ```typescript
 * import { router, json, error } from '@appdeploy/sdk';
 *
 * // Use SDK router/auth helpers directly. Do not re-implement custom router/requireAuth/json helpers.
 * // Reserved platform paths like __appdeploy/* are handled by the platform and should not be defined in app routes.
 *
 * export const handler = router({
 *   'GET /api/items': [async (ctx) => json(await getItems())],
 *   'POST /api/items': [async (ctx) => {
 *     const item = ctx.body as { name: string };
 *     return json({ created: true });
 *   }],
 *   'GET /api/items/:id': [async (ctx) => json({ id: ctx.params.id })],
 * });
 * ```
 */
export declare function router(
    routes: RouterRoutes
): (event: any) => Promise<RouterResponse>;

/** Create a JSON success response */
export declare function json(data: unknown, status?: number): RouterResponse;

/** Create a JSON error response */
export declare function error(message: string, status?: number): RouterResponse;

examples.code:
import { db, increment } from '@appdeploy/sdk';

export async function incrementCounter() {
  // A duplicate returns null without overwriting an existing counter.
  await db.tx.add('counters', [{ id: 'global', value: 0 }]);
  const [updated] = await db.tx.update('counters', [{
    id: 'global', record: { value: increment(1) }
  }], { patch: true });
  if (!updated) throw new Error('Failed to update counter');
  return { id: 'global' };
}

import { db } from '@appdeploy/sdk';

export async function addItem(text) {
  const [id] = await db.add('todos', [{ text, done: false }]);
  if (!id) throw new Error('Failed to add item');
  return id;
}

export async function listItems() {
  return db.list('todos', { limit: 50 });
}

import { db } from '@appdeploy/sdk';

export async function renameUser(userId: string, expectedName: string, name: string) {
  const [updated] = await db.tx.update('users', [{
    id: userId,
    record: { name, obsoleteField: undefined, nullableField: null },
    if: { name: expectedName }
  }], { patch: true });
  // False means the record is missing or the expected name changed.
  return { updated };
}

import { db, increment, isAppDatabaseError } from '@appdeploy/sdk';

type Receipt = { userId: string; amount: number };

// Keep requestId fixed and retain receipts after cancellation; userId comes from authentication.
export async function recordEntry(requestId: string, userId: string, amount: number) {
  async function lookup() {
    const [saved] = await db.get<Receipt>('receipts', [requestId], { consistent: true });
    if (saved && (saved.userId !== userId || saved.amount !== amount)) {
      throw new Error('Request ID belongs to another request');
    }
    return saved;
  }
  if (await lookup()) return { requestId };
  await db.tx.add('totals', [{ id: 'global', amount: 0 }]);
  const entry = db.tx.add('receipts', [{ id: requestId, userId, amount }]);
  const total = db.tx.update('totals', [{
    id: 'global', record: { amount: increment(amount) }
  }], { patch: true });
  try {
    await db.transact([entry, total]);
    return { requestId };
  } catch (err: unknown) {
    if (isAppDatabaseError(err) && (err.code === 'AppDatabaseDuplicateId'
        || err.code === 'AppDatabaseUnknownOutcome') && await lookup()) return { requestId };
    throw err; // Absent receipt does not disprove a pending commit.
  }
}

